const gql = $input.first().json;
if (gql.errors || !gql.data || !gql.data.node) return [];
const item = gql.data.node;
const status = item.fieldValueByName ? item.fieldValueByName.name : '';
if (status !== 'AI Ready') return [];
const content = item.content;
return [{
  json: {
    issue_number: content.number,
    issue_title: content.title,
    issue_body: content.body || '',
    labels: content.labels.nodes.map(l => l.name),
    repo: content.repository.nameWithOwner,
    project_item_node_id: item.id
  }
}];

const data = $input.first().json;
const labels = (data.labels || []).map(l => l.toLowerCase());
const prefixMap = {
  bug: 'b', feature: 'f', refactoring: 'r',
  operations: 'o', 'docs & research': 'd', enhancement: 'e'
};
let prefix = 'e';
for (const [label, p] of Object.entries(prefixMap)) {
  if (labels.includes(label)) { prefix = p; break; }
}
const slug = (data.issue_title || 'task')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-').substring(0, 40).replace(/-$/, '');
const branchName = `${prefix}/#${data.issue_number}-${slug}`;
return [{ json: {
  branch_name: branchName, repo: data.repo, issue_number: data.issue_number,
  issue_title: data.issue_title, issue_body: data.issue_body,
  project_item_node_id: data.project_item_node_id
} }];

const sha = $input.first().json.object.sha;
const ctx = $('Prepare Context').first().json;
return [{ json: { ref: 'refs/heads/' + ctx.branch_name, sha, ...ctx } }];

const ctx = $('Prepare Branch Data').first().json;
const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 2048,
  messages: [{
    role: 'user',
    content: 'You are a senior software architect. Analyze the following GitHub issue and provide your response in EXACTLY this format:

'      + 'SUMMARY: [one sentence describing the implementation approach]
'      + '---
'      + '[full detailed analysis including:
'      + '1. Implementation approach (step-by-step)
'      + '2. Files likely affected -- list each file as a repo-relative path in backticks (e.g. `app/src/main.py`). If unsure of exact path, give your best guess.
'      + '3. Risks and considerations
'      + '4. Estimated complexity (Low/Medium/High)]

'      + 'Issue title: ' + ctx.issue_title + '

'      + 'Issue body:
' + ctx.issue_body
  }]
};
return [{ json: requestBody }];

const claudeText = $input.first().json.content[0].text;
const ctx = $('Prepare Branch Data').first().json;
// Parse SUMMARY line and details
let summary = 'Implementation analysis complete for issue #' + ctx.issue_number + '.';
let details = claudeText;
const parts = claudeText.split(/^---$/m);
if (parts.length >= 2) {
  const summaryLine = parts[0].trim();
  const match = summaryLine.match(/^SUMMARY:\s*(.+)/i);
  if (match) summary = match[1].trim();
  details = parts.slice(1).join('---').trim();
}
const body = '> \uD83E\uDD16 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**' + summary + '**\n\n'
  + '<details>\n<summary>View full implementation analysis</summary>\n\n'
  + details + '\n\n'
  + '---\n'
  + '*Branch: `' + ctx.branch_name + '`*\n\n'
  + '</details>';
return [{ json: { body, repo: ctx.repo, issue_number: ctx.issue_number, analysis_text: claudeText, branch_name: ctx.branch_name, issue_title: ctx.issue_title, issue_body: ctx.issue_body, sha: ctx.sha } }];

// Pass through from Format Output
const data = $input.first().json;
return [{ json: data }];

const tree = $input.first().json.tree || [];
const ctx = $('Build Analysis Comment').first().json;
const analysisText = ctx.analysis_text || '';

// Build set of valid tree paths (blobs only)
const blobs = tree.filter(t => t.type === 'blob');
const treePaths = new Set(blobs.map(t => t.path));

// Strategy 1: Extract backticked paths from analysis and cross-ref with tree
const pathMatches = analysisText.match(/`([^`]+\.[a-zA-Z0-9]+)`/g) || [];
const candidatePaths = pathMatches.map(m => m.replace(/`/g, '').trim());
const seen = new Set();
const matched = [];
for (const p of candidatePaths) {
  if (treePaths.has(p) && !seen.has(p)) {
    seen.add(p);
    matched.push(p);
  }
}

let filesToFetch = matched;

// Strategy 2: If no exact matches, select all source code files
if (filesToFetch.length === 0) {
  const sourceExts = new Set(['py','js','ts','tsx','jsx','html','css','scss','vue','svelte','go','rs','java','rb','php','c','cpp','h','hpp']);
  const ignorePrefixes = ['.github/', 'scripts/', 'node_modules/', '.'];
  filesToFetch = blobs
    .map(t => t.path)
    .filter(p => {
      const ext = p.split('.').pop().toLowerCase();
      if (!sourceExts.has(ext)) return false;
      for (const prefix of ignorePrefixes) {
        if (p.startsWith(prefix)) return false;
      }
      return true;
    });
}

// Always include CLAUDE.md if it exists and not already included
if (treePaths.has('CLAUDE.md') && !filesToFetch.includes('CLAUDE.md')) {
  filesToFetch.unshift('CLAUDE.md');
}

// Always include test files for context (so Claude can assess test coverage)
const testDirs = ['tests/', 'test/', 'e2e/', '__tests__/'];
const testExts = new Set(['spec.js','test.js','spec.ts','test.ts','spec.jsx','test.jsx','spec.tsx','test.tsx']);
for (const blobPath of blobs.map(t => t.path)) {
  if (filesToFetch.includes(blobPath)) continue;
  const inTestDir = testDirs.some(d => blobPath.includes(d));
  const fileName = blobPath.split('/').pop() || '';
  const isTestFile = testExts.has(fileName.split('.').slice(1).join('.'));
  if (inTestDir || isTestFile) {
    filesToFetch.push(blobPath);
  }
}

// Cap at 15 files
const capped = filesToFetch.slice(0, 15);

if (capped.length === 0) {
  return [{ json: { path: '', skip: true } }];
}

return capped.map(p => ({ json: { path: p } }));

const ctx = $('Build Analysis Comment').first().json;
const claudeMdRaw = $('Fetch CLAUDE.md').first().json.content || '';
const tree = $('Fetch File Tree').first().json.tree || [];

// Decode CLAUDE.md
let claudeMd = '';
try { claudeMd = Buffer.from(claudeMdRaw.replace(/\n/g, ''), 'base64').toString('utf8'); } catch(e) {}

// Build file tree string
const fileTree = tree.filter(t => t.type === 'blob').map(t => t.path).join('\n');

// Collect fetched file contents, SHA map, and content map for diff checking
const shaMap = {};
const contentMap = {};
let fileContents = '';

const inputItems = $input.all();
for (const item of inputItems) {
  const d = item.json;
  if (!d.path || !d.content) continue;
  if (d.sha) shaMap[d.path] = d.sha;
  let decoded = '';
  try { decoded = Buffer.from(d.content.replace(/\n/g, ''), 'base64').toString('utf8'); } catch(e) { continue; }
  contentMap[d.path] = decoded;
  if (decoded.length > 30000) {
    fileContents += '### ' + d.path + '\n(file too large, ' + decoded.length + ' chars \u2014 skipped)\n\n';
    continue;
  }
  fileContents += '### ' + d.path + '\n```\n' + decoded + '\n```\n\n';
}

const repo = ctx.repo;
const branch_name = ctx.branch_name;

const system_message = 'You are an expert software developer implementing changes to a GitHub repository.\n\n'
  + 'REPOSITORY: ' + repo + '\n'
  + 'BRANCH: ' + branch_name + '\n\n'
  + (claudeMd ? '## Project Context (CLAUDE.md)\n\n' + claudeMd + '\n\n' : '')
  + '## Rules\n\n'
  + '- Do NOT modify .github/workflows/ files or deploy/CI scripts\n'
  + '- Do NOT modify files unrelated to the issue\n'
  + '- Follow existing code conventions and patterns in the repository\n'
  + '- Implement the feature FULLY and COMPLETELY \u2014 do not add stubs, placeholders, or partial implementations\n'
  + '- Only output FILE blocks for files you are ACTUALLY changing \u2014 do not output files with no modifications\n\n'
  + '## Testing\n\n'
  + '- Review the existing test files provided below to understand current test coverage\n'
  + '- If your changes add new user-facing behavior NOT already covered by existing tests, add or update test files\n'
  + '- If existing tests already cover the feature you are implementing, do NOT add duplicate tests\n'
  + '- Follow the existing test patterns, naming conventions, and framework used in the project\n'
  + '- Test files are output as FILE blocks just like source files\n\n'
  + '## Output Format\n\n'
  + 'Output ONLY the changed files using this exact format (one block per file):\n\n'
  + 'FILE: path/to/file.ext\n'
  + '```\n'
  + 'full file content here\n'
  + '```\n\n'
  + 'After all FILE blocks, add exactly one line:\n\n'
  + 'SUMMARY: One sentence describing what was implemented\n\n'
  + 'IMPORTANT:\n'
  + '- Each FILE block must contain the COMPLETE file content (not a diff/patch)\n'
  + '- Only output files that have ACTUAL substantive changes\n'
  + '- For new files, use the full intended path';

const user_message = '## Task\n\n'
  + 'Implement the following GitHub issue.\n\n'
  + '**Issue #' + ctx.issue_number + ': ' + ctx.issue_title + '**\n\n'
  + ctx.issue_body + '\n\n'
  + '## AI Analysis (advisory only)\n\n'
  + 'NOTE: The analysis below may reference file paths that do NOT exist in this repository. '
  + 'Ignore any file paths from the analysis that are not present in the actual file tree below. '
  + 'Use the actual repository structure and file contents to guide your implementation.\n\n'
  + ctx.analysis_text + '\n\n'
  + '## Repository File Tree (actual)\n\n'
  + '```\n' + fileTree + '\n```\n\n'
  + (fileContents ? '## Current File Contents\n\n' + fileContents + '\n' : '')
  + '## Instructions\n\n'
  + 'Implement the feature described in the issue COMPLETELY. '
  + 'Study the existing code carefully and make all necessary changes across all relevant files. '
  + 'Include CSS/styling changes, HTML structure changes, and JavaScript logic changes as needed. '
  + 'Output ONLY the FILE blocks for files with actual changes, followed by SUMMARY.';

return [{ json: {
  model: 'claude-sonnet-4-20250514',
  max_tokens: 16384,
  system: system_message,
  messages: [{ role: 'user', content: user_message }],
  temperature: 1,
  _shaMap: shaMap,
  _contentMap: contentMap
} }];

const response = $input.first().json;
const ctx = $('Build Analysis Comment').first().json;
const claudeText = (response.content || []).filter(c => c.type === 'text').map(c => c.text).join('\n');

// Get SHA map and content map from Build Full Prompt
const shaMap = $('Build Full Prompt').first().json._shaMap || {};
const contentMap = $('Build Full Prompt').first().json._contentMap || {};

// Parse FILE blocks
const fileRegex = /FILE:\s*(.+?)\n```[\w]*\n([\s\S]*?)\n```/g;
const allFiles = [];
let match;
while ((match = fileRegex.exec(claudeText)) !== null) {
  const path = match[1].trim();
  const content = match[2];
  if (path && content !== undefined) {
    allFiles.push({ path, content, sha: shaMap[path] || '' });
  }
}

// Filter out files with no actual changes (compare against original content)
const files = allFiles.filter(f => {
  const original = contentMap[f.path];
  if (!original) return true; // new file, always include
  return f.content.trim() !== original.trim();
});

// Parse SUMMARY
let summary = 'Auto-develop completed';
const summaryMatch = claudeText.match(/SUMMARY:\s*(.+)/);
if (summaryMatch) summary = summaryMatch[1].trim();

const skippedCount = allFiles.length - files.length;

if (files.length === 0) {
  return [{ json: {
    path: '', content_text: '', message: '', sha: '', skip: true,
    _meta: { summary, fileCount: 0, skippedCount, fileList: '- (no files with actual changes)', repo: ctx.repo, branch_name: ctx.branch_name, issue_number: ctx.issue_number, claude_output: claudeText }
  } }];
}

const fileList = files.map(f => '- `' + f.path + '`').join('\n');
const meta = { summary, fileCount: files.length, skippedCount, fileList, repo: ctx.repo, branch_name: ctx.branch_name, issue_number: ctx.issue_number, claude_output: claudeText };

return files.map(f => ({
  json: {
    path: f.path,
    content_text: f.content,
    message: '[auto-develop] Update ' + f.path,
    sha: f.sha,
    repo: ctx.repo,
    branch: ctx.branch_name,
    _meta: meta
  }
}));

// Get metadata from Parse & Prepare Commits
const items = $('Parse & Prepare Commits').all();
const meta = items[0].json._meta || {};

const fileList = meta.fileList || '- (no files)';
const fileCount = meta.fileCount || 0;
const summary = meta.summary || 'Auto-develop completed';
const repo = meta.repo;
const issue_number = meta.issue_number;
const branch_name = meta.branch_name;

const body = '> 🤖 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**Auto-develop: ' + summary + '**\n\n'
  + '<details>\n<summary>View committed files (' + fileCount + ')</summary>\n\n'
  + fileList + '\n\n'
  + '---\n'
  + '*Branch: `' + branch_name + '`*\n'
  + '*CI will run automatically. If tests pass, a PR will be created by WF03.*\n\n'
  + '</details>';

return [{ json: { body, repo, issue_number } }];
